# The CANON repo's own CI — Claudinite's test suite + its own conformance sweep
# on every PR. Not consumer wiring (consumers ship no workflow, #385).
name: CI
on:
  pull_request:
  push:
    branches: [main]
defaults:
  run:
    shell: bash
jobs:
  test-and-conformance:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0
          # Check out the PR's real head, not the synthetic refs/pull/N/merge commit
          # actions/checkout uses by default — otherwise HEAD is an ephemeral merge of
          # the branch into main, which the work-scoped squash-merge-history check would
          # (correctly, for that synthetic commit) flag. This makes CI evaluate exactly
          # what the local Stop hook does: the branch tip. Falls back to github.sha on push.
          ref: ${{ github.event.pull_request.head.sha || github.sha }}
      - uses: actions/setup-node@v4
        with:
          node-version: 20
      - name: Unit tests
        # engine-tests/ mirrors engine/'s inner structure (#385 — engine/ ships to consumers exactly as-is, tests stay canon-side); each pack carries its own tests inside its tree, the home's local packs included; routines/fleet/ carries the planner tests.
        # nullglob: a location with no tests drops out instead of reaching node as a literal pattern.
        run: |
          shopt -s nullglob
          tests=(engine-tests/*.test.mjs engine-tests/*/*.test.mjs packs-tests/*.test.mjs packs-tests/*/*.test.mjs packs-tests/*/skills/*/*.test.mjs routines/*/*.test.mjs .claudinite/local/packs/*/*.test.mjs .claudinite/local/packs/*/skills/*/*.test.mjs .claudinite/local_packs/*/*.test.mjs .claudinite/local_packs/*/skills/*/*.test.mjs)
          node --test "${tests[@]}"
      - name: Conformance sweep
        # The world sweep's home is the test/CI flow (not the Stop hook, which
        # carries only the work scope) — this canon repo models the pattern
        # bootstrap wires into consumers. World only: the work scope judges a
        # session's change and runs at that session's Stop hook, not here.
        run: node engine/checks/check_the_world.mjs
      - name: Promote write-surface gate
===
  } finally { cleanup(root); }
});

test('--list emits the machine-readable rule catalog', () => {
  const root = makeRepo({ changed: {} });
  try {
    const r = runCli(root, '--list');
    assert.equal(r.status, 0);
    for (const id of ['reference-integrity', 'markdown-link-labels', 'task-lifecycle',
                      'warning-suppression', 'file-placement',
                      'squash-merge-history']) {
      assert.match(r.stdout, new RegExp(`^${id}\t`, 'm'));
    }
  } finally { cleanup(root); }
});

test("a pack's rules run only when it is declared", () => {
  // A marker (here a workflow) only suspects a pack is wanted — it never forces
  // one. So an undeclared github-actions pack stays silent (its rules don't run),
  // and declaring it turns them on. Whether to declare is the project's call.
  const wf = { '.github/workflows/x.yml': 'name: x\non: push\njobs:\n  t:\n    runs-on: ubuntu-latest\n    if: ${{ secrets.T }}\n    steps:\n      - run: echo hi\n' };
===
    base: { 'deep/far/other.md': 'x\n' },
    changed: { 'doc.md': 'see [other](../deep/far/other.md)\n' },
  });
  try {
    assert.equal(run(filePlacement, root).length, 0);
  } finally { cleanup(root); }
});

test('squash-merge-history: flags a merge the work introduces, silent on linear history and pre-existing main merges', () => {
  const linear = makeRepo({ changed: { 'f.txt': 'x\n' } });

  // A merge commit on the feature branch itself — the current change introduces it → fires.
  const introduced = makeRepo({ changed: { 'f.txt': 'x\n' } });
  git(introduced, 'checkout', '-q', '-b', 'side');
  writeFiles(introduced, { 's.txt': 'x\n' });
  git(introduced, 'add', '-A');
  git(introduced, 'commit', '-q', '-m', 'side work');
  git(introduced, 'checkout', '-q', 'feature');
  git(introduced, 'merge', '-q', '--no-ff', '-m', 'merge side into feature', 'side');

  // A merge commit already on main, before the branch's work — the repo's history, not the work → silent.
  const preexisting = makeRepo({ changed: {} });
  git(preexisting, 'checkout', '-q', 'main');
  git(preexisting, 'checkout', '-q', '-b', 'side');
  writeFiles(preexisting, { 's.txt': 'x\n' });
  git(preexisting, 'add', '-A');
  git(preexisting, 'commit', '-q', '-m', 'side work');
  git(preexisting, 'checkout', '-q', 'main');
  git(preexisting, 'merge', '-q', '--no-ff', '-m', 'merge side', 'side');
  git(preexisting, 'checkout', '-q', '-B', 'feature', 'main'); // branch fresh off post-merge main
  writeFiles(preexisting, { 'w.txt': 'x\n' });
  git(preexisting, 'add', '-A');
  git(preexisting, 'commit', '-q', '-m', 'feature work');

  try {
    const findings = run(squashMergeHistory, introduced);

