commit('h1', 420);
at(0, 'checkout', '-q', 'zed');
at(480, 'merge', '-q', '--no-ff', '-m', 'base takes the shared merge', 'pea');
at(0, 'branch', '-f', 'basebr', 'zed');
at(0, 'checkout', '-q', 'feature');

